(11159, 1430, 'tl-post-header', 'The energy industry in the United States changed dramatically over the past 10 years. Innovation and regulation both played significant roles.'),
(11160, 1430, '_author_email_2', 'field_588bce1fe7e83'),
(11161, 1430, '_author_title_2', 'field_588bce12e7e82'),
(11162, 1430, 'author_email_2', ''),
(11163, 1430, 'author_title_2', ''),
(11164, 1430, '_author_title_1', 'field_588bcdebe7e7f'),
